using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Text.Json;
using System.Security.Cryptography;

namespace FileProcessingService
{
    public interface IFileMetadata
    {
        string FileName { get; }
        string ContentType { get; }
        long Size { get; }
    }

    public class TrustedMetadata : IFileMetadata
    {
        public string FileName { get; set; }
        public string ContentType { get; set; }
        public long Size { get; set; }
        public bool IsVerified { get; set; } = true;
        public string InternalPath { get; set; }
    }

    public class UserMetadata : IFileMetadata
    {
        public string FileName { get; set; }
        public string ContentType { get; set; }
        public long Size { get; set; }
        public string UserId { get; set; }
    }

    public class ProcessingContext
    {
        private readonly ConcurrentDictionary<string, object> _registry = new();
        private readonly SemaphoreSlim _semaphore = new(1, 1);

        public async Task RegisterAsync(string jobId, IFileMetadata metadata)
        {
            _registry[jobId] = metadata;
            await Task.Delay(10); // Simulate async registration
        }

        public async Task<object> RetrieveAsync(string jobId)
        {
            await _semaphore.WaitAsync();
            try
            {
                _registry.TryGetValue(jobId, out var result);
                return result;
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public async Task UpdateRegistrationAsync(string jobId, IFileMetadata metadata)
        {
            await Task.Yield();
            _registry[jobId] = metadata;
        }
    }

    public class FileProcessor
    {
        private readonly ProcessingContext _context;
        private readonly string _basePath;

        public FileProcessor(ProcessingContext context, string basePath)
        {
            _context = context;
            _basePath = basePath;
        }

        public async Task<string> InitiateProcessingAsync(string jobId, UserMetadata userMeta)
        {
            var sanitizedName = SanitizeFileName(userMeta.FileName);
            userMeta.FileName = sanitizedName;

            if (!IsAllowedContentType(userMeta.ContentType))
                throw new InvalidOperationException("Disallowed content type");

            await _context.RegisterAsync(jobId, userMeta);
            return jobId;
        }

        public async Task<string> ElevateToTrustedAsync(string jobId, byte[] fileContent)
        {
            var hash = ComputeHash(fileContent);
            var registered = await _context.RetrieveAsync(jobId);

            if (registered is UserMetadata um)
            {
                var trusted = new TrustedMetadata
                {
                    FileName = um.FileName,
                    ContentType = um.ContentType,
                    Size = fileContent.Length,
                    IsVerified = true,
                    InternalPath = Path.Combine(_basePath, hash, um.FileName)
                };
                await _context.UpdateRegistrationAsync(jobId, trusted);
                return trusted.InternalPath;
            }

            throw new InvalidOperationException("Invalid registration state");
        }

        public async Task<Stream> FinalizeAsync(string jobId, string requestedPath)
        {
            var registered = await _context.RetrieveAsync(jobId);

            if (registered is IFileMetadata metadata)
            {
                var resolvedPath = ResolveOutputPath(registered, requestedPath);
                await Task.Delay(5);
                return new MemoryStream(System.Text.Encoding.UTF8.GetBytes(
                    $"Writing to: {resolvedPath}"));
            }

            throw new InvalidOperationException("Job not found");
        }

        private string ResolveOutputPath(object registered, string requestedPath)
        {
            // Type-based dispatch for path resolution
            if (registered is TrustedMetadata tm && tm.IsVerified)
            {
                // Trusted metadata: use the pre-validated InternalPath directly
                return tm.InternalPath;
            }
            else if (registered is UserMetadata um)
            {
                // User metadata: apply strict path constraints
                var safe = Path.Combine(_basePath, "user_uploads", SanitizeFileName(um.FileName));
                return safe;
            }
            else
            {
                return Path.Combine(_basePath, "unknown", "output.bin");
            }
        }

        public async Task InjectTrustedOverrideAsync(string jobId, string overridePath)
        {
            // Administrative endpoint - registers a trusted path override
            // This should only be called by internal services
            var current = await _context.RetrieveAsync(jobId);
            if (current is TrustedMetadata tm)
            {
                tm.InternalPath = overridePath;
                await _context.UpdateRegistrationAsync(jobId, tm);
            }
        }

        private string SanitizeFileName(string fileName)
        {
            var name = Path.GetFileName(fileName);
            return name.Replace("..", "").Replace("/", "").Replace("\\", "");
        }

        private bool IsAllowedContentType(string contentType)
        {
            var allowed = new[] { "image/png", "image/jpeg", "application/pdf", "text/plain" };
            return Array.Exists(allowed, a => a == contentType);
        }

        private string ComputeHash(byte[] data)
        {
            using var sha = SHA256.Create();
            var hash = sha.ComputeHash(data);
            return Convert.ToHexString(hash).Substring(0, 16).ToLowerInvariant();
        }
    }

    public class ConcurrentAttackScenario
    {
        public static async Task DemonstrateRaceAsync()
        {
            var context = new ProcessingContext();
            var processor = new FileProcessor(context, "/var/data/files");

            var jobId = "job-12345";
            var userMeta = new UserMetadata
            {
                FileName = "innocent.png",
                ContentType = "image/png",
                Size = 1024,
                UserId = "user-1"
            };

            await processor.InitiateProcessingAsync(jobId, userMeta);

            // Race: Elevate and Finalize concurrently
            var elevateTask = processor.ElevateToTrustedAsync(jobId, new byte[] { 0x89, 0x50 });

            // Concurrent call to finalize before elevation completes
            // The registry may still hold UserMetadata OR TrustedMetadata
            // But the real attack: after elevation, inject a path override
            await elevateTask;

            // Now the attacker calls InjectTrustedOverride via a confused deputy
            // Because the object is TrustedMetadata, the override is accepted
            await processor.InjectTrustedOverrideAsync(jobId, "/etc/shadow");

            // FinalizeAsync trusts TrustedMetadata.InternalPath without re-validation
            var result = await processor.FinalizeAsync(jobId, "/ignored");
            using var reader = new StreamReader(result);
            Console.WriteLine(await reader.ReadToEndAsync());
        }
    }
}
